use std::fmt::Write;
use std::fs;

use axo::ext::objects;

const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/docs/extension-api.md");

fn push_cell(output: &mut String, text: &str) {
    for ch in text.chars() {
        match ch {
            '`' => {}
            '|' => output.push_str("\\|"),
            '\n' | '\r' => output.push(' '),
            _ => output.push(ch),
        }
    }
}

fn reference() -> String {
    let mut output = String::from(
        "# Extension API reference\n\n\
         <!-- Generated by cargo test -p axo --test ext_reference; do not edit. -->\n\n\
         Extensions are trusted code; nothing here is a sandbox.\n",
    );
    for object in objects() {
        writeln!(output, "\n## {}\n", object.name).unwrap();
        if object.name != "types" {
            output.push_str("| Method | Parameters | Summary |\n| --- | --- | --- |\n");
            for meta in object.blocks.iter().flat_map(|block| &block.entries) {
                if meta.skip.is_some() {
                    continue;
                }
                output.push_str("| ");
                push_cell(&mut output, meta.name);
                output.push_str(" | ");
                for (index, param) in meta.params.iter().enumerate() {
                    if index != 0 {
                        output.push_str(", ");
                    }
                    push_cell(&mut output, param.name);
                    if param.optional {
                        output.push('?');
                    }
                }
                output.push_str(" | ");
                // Doc comments wrap; the first paragraph is the whole summary sentence.
                let summary = meta
                    .doc
                    .lines()
                    .map(str::trim)
                    .take_while(|line| !line.is_empty());
                push_cell(&mut output, &summary.collect::<Vec<_>>().join(" "));
                output.push_str(" |\n");
            }
            output.push('\n');
        }
        output.push_str("### Withheld\n\n| Rust method | Reason |\n| --- | --- |\n");
        for block in &object.blocks {
            for meta in &block.entries {
                if let Some(reason) = meta.skip {
                    output.push_str("| ");
                    push_cell(&mut output, block.name);
                    output.push_str("::");
                    push_cell(&mut output, meta.rust_name);
                    output.push_str(" | ");
                    push_cell(&mut output, reason);
                    output.push_str(" |\n");
                }
            }
        }
    }
    output.push_str(
        "\n## Served by the extension bridge\n\n\
         - session: subscribe.\n\
         - host: session lifecycle methods (create, open, fork, close), typed as HostLifecycle in the SDK bindings. Without a lifecycle hook, these calls are refused with no_lifecycle.\n\
         - models: stream.\n",
    );
    output
}

#[test]
fn extension_api_reference_is_current() {
    let fresh = reference();
    if std::env::var("UPDATE_BINDINGS").as_deref() == Ok("1") {
        fs::write(PATH, fresh).unwrap();
    } else {
        assert!(
            fs::read_to_string(PATH).ok().as_deref() == Some(fresh.as_str()),
            "crates/axo/docs/extension-api.md is stale; run UPDATE_BINDINGS=1 cargo test -p axo --test ext_reference"
        );
    }
}
